
// Compact, lossless LZSS encoding of HTML to fit Railway Function's startCommand limit.
function dtDecodeLzss(data:string):string{
const bytes=Buffer.from(data,"base64"),out:number[]=[];
for(let i=0;i<bytes.length;){
const flags=bytes[i++];
for(let b=0;b<8&&i<bytes.length;b++){
if(flags&(1<<b)){
const distance=(bytes[i++]<<8)|bytes[i++],length=bytes[i++];
if(!distance||distance>out.length)throw Error("Arquivo inválido");
for(let k=0;k<length;k++)out.push(out[out.length-distance]);
}else out.push(bytes[i++])
}
}
return new TextDecoder().decode(Uint8Array.from(out))
}
