if(path==="/api/listings/autosave"&&req.method==="POST"){
if(!configured())return json(503,{error:"Banco ainda não configurado."});
if(!dtSameOrigin(req,url))return json(403,{error:"Origem inválida."});
const s=await getUser(req);if(!s)return json(401,{error:"Entre na conta para salvar automaticamente."});
if(Number(req.headers.get("content-length")||0)>31*1024*1024)return json(413,{error:"Limite de 30 MB por operação."});
let form:FormData;try{form=await req.formData()}catch{return json(400,{error:"Dados inválidos."})}
const title=String(form.get("title")||"").trim().slice(0,180),description=String(form.get("description")||"").trim().slice(0,4500);
const item=String(form.get("item")||title||"Produto").trim().slice(0,100);
const conditionInput=String(form.get("condition")||""),condition=["novo","otimo","bom","regular"].includes(conditionInput)?conditionInput:"nao_informado";
const priceInput=String(form.get("price")||"").trim(),price=priceInput?Number(priceInput.replace(",",".")):null;
const existing=String(form.get("listingId")||"");
if(!title||!description||!item||existing&&!dtIsUUID(existing))return json(400,{error:"Anúncio inválido."});
if(price!==null&&(!Number.isFinite(price)||price<0||price>100000000))return json(400,{error:"Preço inválido."});
const original=form.getAll("original").filter((x:any)=>typeof x!=="string") as File[];
const generated=form.getAll("generated").filter((x:any)=>typeof x!=="string") as File[];
if(original.length>4||generated.length>4)return json(400,{error:"Até quatro fotos por operação."});
for(const file of [...original,...generated]){
if(!dtAllowedImageType.has(file.type)||file.size>5242880||file.size<100)return json(415,{error:"Use JPG, PNG ou WebP de até 5 MB."});
if(!dtValidImageHead(new Uint8Array(await file.slice(0,12).arrayBuffer()),file.type))return json(415,{error:"Arquivo de imagem inválido."});
}
const headers=dtDbHeaders(s.token,{"content-type":"application/json","prefer":"return=representation"});
let id=existing;
const row={item_name:item,title,description,condition,price};
try{
if(existing){
const response=await fetch(origin()+"/rest/v1/dt_listings?id=eq."+existing+"&user_id=eq."+encodeURIComponent(s.user.id),{method:"PATCH",headers,body:JSON.stringify(row),signal:AbortSignal.timeout(15000)});
if(!response.ok)return json(503,{error:"Não foi possível atualizar o rascunho."});
const saved:any=await response.json();if(!saved?.length)return json(404,{error:"Rascunho não encontrado."});
}else{
const response=await fetch(origin()+"/rest/v1/dt_listings",{method:"POST",headers,body:JSON.stringify({...row,user_id:s.user.id,status:"draft"}),signal:AbortSignal.timeout(15000)});
if(!response.ok)return json(503,{error:"Não foi possível criar rascunho."});
const saved:any=await response.json();id=saved?.[0]?.id||"";
if(!dtIsUUID(id))return json(503,{error:"Identificador inválido."});
}
const style=String(form.get("style")||"neutral")==="white"?"white":"neutral";
const kind=String(form.get("generatedKind")||"ai")==="faithful"?"faithful":"ai";
let count=0;
for(const [files,type] of [[original,"original"],[generated,kind]] as [File[],string][]){
for(const file of files){
const ext=file.type==="image/png"?"png":file.type==="image/jpeg"?"jpg":"webp";
const storagePath=s.user.id+"/"+id+"/"+type+"-"+crypto.randomUUID()+"."+ext;
const upload=await fetch(origin()+"/storage/v1/object/dt-private/"+storagePath,{method:"POST",headers:dtDbHeaders(s.token,{"content-type":file.type,"x-upsert":"false"}),body:file,signal:AbortSignal.timeout(25000)});
if(!upload.ok)return json(503,{error:"Rascunho salvo, mas uma imagem não foi armazenada.",id,photosSaved:count});
const record=await fetch(origin()+"/rest/v1/dt_listing_images",{method:"POST",headers:dtDbHeaders(s.token,{"content-type":"application/json","prefer":"return=minimal"}),body:JSON.stringify({listing_id:id,user_id:s.user.id,storage_path:storagePath,kind:type,style:type==="original"?null:style,verified:type==="faithful"}),signal:AbortSignal.timeout(15000)});
if(!record.ok)return json(503,{error:"Imagem enviada, mas não registrada no histórico.",id,photosSaved:count});
count++;
}
}
return json(200,{saved:true,id,photosSaved:count});
}catch(e){console.warn("dt_autosave_error",String(e).slice(0,140));return json(503,{error:"Falha ao salvar na nuvem."})}
}

